let lang='es',type=location.hash==='#de-paso'?'paso':'all',savedOnly=false,active=null,photo=0,lastFocus,toastTimer;let saved=new Set();try{lang=sessionStorage.getItem('lavita-language')==='en'?'en':'es';saved=new Set(JSON.parse(sessionStorage.getItem('lavita-saved-stays')||'[]'));}catch{}
const t=k=>copy[lang][k]||k,money=n=>new Intl.NumberFormat(lang==='es'?'es-MX':'en-US',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n)+' MXN',dialog=$('#stay-dialog');
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function plus(day,n){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
$('#stay-checkin').min=today();$('#stay-checkin').value=plus(today(),1);$('#stay-checkout').value=plus(today(),3);$('#stay-checkout').min=plus(today(),2);
let trip={start:$('#stay-checkin').value,end:$('#stay-checkout').value,guests:2,hours:6};
const nights=()=>Math.round((Date.parse(trip.end)-Date.parse(trip.start))/86400000),date=d=>new Intl.DateTimeFormat(lang==='es'?'es-MX':'en-US',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
function baseRate(p){return p.type==='paso'?Math.round(p.demoPrice*trip.hours/6):p.demoPrice;}
function price(p){const short=p.type==='paso',count=p.type==='hostel'?trip.guests:(p.type==='hotel'||short)?Math.ceil(trip.guests/2):1,discount=(short||nights()>=p.demoOfferNights)?p.demoDiscount:0,unit=Math.round(baseRate(p)*(100-discount)/100),periods=short?1:nights();return {count,discount,unit,periods,base:baseRate(p)*periods*count,total:unit*periods*count};}
function unitText(p){return p.type==='paso'?`${t('blockUnit')} ${trip.hours} h`:t(p.type==='hostel'?'personNight':p.type==='hotel'?'roomNight':'aptNight');}
function offerText(p){return p.type==='paso'?`${t('block')} ${trip.hours} h · ${t('demoPromo')}`:`${t('minStay')} ${p.demoOfferNights} ${t('nights')} · ${t('demoPromo')}`;}
function tripText(p){return p?.type==='paso'||type==='paso'?`${date(trip.start)} · ${t('block')} ${trip.hours} h · DEMO`:`${date(trip.start)} — ${date(trip.end)} · ${nights()} ${t('nights')}`;}
function hasOffer(p){return p.demoDiscount>0;}
function list(){const q=norm($('#stay-search').value),zone=$('#stay-zone').value,budget=+$('#stay-budget').value,amen=$$('[data-amenity]:checked').map(x=>x.value);let result=stays.filter(p=>(type==='all'||p.type===type)&&(!zone||p.zone===zone)&&(!savedOnly||saved.has(p.id))&&(!$('#stay-offers').checked||hasOffer(p))&&price(p).unit<=budget&&amen.every(x=>p.amenities.includes(x))&&(!p.capacity||p.capacity>=trip.guests)&&(!q||norm(p.name+' '+p.area+' '+t(p.type)+' '+p.description[lang]+' '+p.amenities.map(t).join(' ')).includes(q)));const sort=$('#stay-sort').value;if(sort==='price-up')result.sort((a,b)=>price(a).unit-price(b).unit);if(sort==='price-down')result.sort((a,b)=>price(b).unit-price(a).unit);if(sort==='name')result.sort((a,b)=>a.name.localeCompare(b.name));return result;}
function card(p){const v=price(p);return `<article class="stay-card"><button class="stay-favorite" data-save="${p.id}" aria-pressed="${saved.has(p.id)}" aria-label="${saved.has(p.id)?t('unsave'):t('save')} · ${esc(p.name)}">${saved.has(p.id)?'♥':'♡'}</button><button class="stay-card-open" data-stay="${p.id}" aria-label="${t('view')} · ${esc(p.name)}"><div class="stay-photo"><img src="${esc(p.images[0].local)}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="550" height="360"><span class="stay-kind">${t(p.type)}</span></div><div class="stay-card-body"><div class="stay-location"><span>${esc(p.area)}</span><span>${p.type==='airbnb'?'Airbnb':'↗'}</span></div><h3>${esc(p.name)}</h3><p class="stay-amenities">${p.capacity?`${t('capacity')} ${p.capacity} ${t('people')} · `:''}${p.amenities.slice(0,3).map(t).join(' · ')}</p><div class="stay-price">${v.discount?`<s>${money(baseRate(p))}</s>`:''}<strong>${money(v.unit)}</strong></div><small class="stay-source-type">${unitText(p)} · ${t('demoOnly')}</small><p class="stay-total">${money(v.total)} ${t('total')}</p><div class="stay-card-note"><span>${hasOffer(p)?`−${p.demoDiscount}% · ${offerText(p)}`:t('baseExample')}</span><span>↗</span></div></div></button></article>`;}
function render(){const short=type==='paso';$('#stay-checkout-field').hidden=short;$('#stay-checkout').disabled=short;$('#stay-duration-field').hidden=!short;$('#stay-short-note').hidden=!short;const data=list();$$('[data-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.type===type)));$('#saved-only').setAttribute('aria-pressed',String(savedOnly));$('#saved-count').textContent=saved.size;$('#budget-value').textContent=money(+$('#stay-budget').value);$('#stay-count').textContent=`${data.length} ${t(data.length===1?'property':'properties')}`;$('#stay-trip-summary').textContent=`${tripText()} · ${trip.guests} ${t('people')} · ${t('resultsNote')}`;$('#stay-results').innerHTML=data.length?data.map(card).join(''):`<div class="stay-empty"><h3>${t('empty')}</h3><p>${t('emptyText')}</p><button data-reset>${t('clear')}</button></div>`;const promos=data.filter(hasOffer);$('.stay-promos').hidden=!promos.length;$('#stay-promo-track').innerHTML=promos.slice(0,10).map(p=>`<button class="stay-promo" data-stay="${p.id}" aria-label="${esc(p.name)} · ${t('demoPromo')}"><img src="${esc(p.images[0].local)}" alt="" loading="lazy" width="101" height="108"><span><small>${t(p.type)} · DEMO</small><b>−${p.demoDiscount}%</b><strong>${esc(p.name)}</strong><em>${offerText(p)}</em></span></button>`).join('');}
function interfaceText(){document.documentElement.lang=lang;document.title=t('stays')+' · La Vita Roma Condesa';$$('[data-i18n]').forEach(x=>x.textContent=t(x.dataset.i18n));$('#language').value=lang;$('#stay-search').placeholder=t('searchPlaceholder');$('#stay-search').setAttribute('aria-label',t('searchPlaceholder'));$('#stay-close').setAttribute('aria-label',t('close'));$('#promos-prev').setAttribute('aria-label',t('prevPromo'));$('#promos-next').setAttribute('aria-label',t('nextPromo'));$('.stay-types').setAttribute('aria-label',t('typeLabel'));if(accountsEnabled){refreshAccountHeader();}else{try{const p=JSON.parse(sessionStorage.getItem('lavita-community-demo'));if(p&&typeof p.name==='string'&&Number.isFinite(p.points)){$('#profile-name').textContent=p.name;$('#profile-points').textContent=p.points.toLocaleString()+' pts · Demo';$('.avatar').textContent=p.name.slice(0,1);}}catch{}}render();}
function detail(p){active=p;photo=0;const v=price(p),imgs=p.images;lastFocus=document.activeElement;$('#stay-dialog-body').innerHTML=`<div class="stay-detail-gallery"><img id="stay-detail-image" src="${esc(imgs[0].local)}" alt="${esc(p.name)}" width="1100" height="700">${imgs.length>1?`<div class="stay-gallery-controls"><button data-photo="-1" aria-label="${t('prevPhoto')}">‹</button><span id="stay-photo-count">1 / ${imgs.length}</span><button data-photo="1" aria-label="${t('nextPhoto')}">›</button></div>`:''}</div><div class="stay-detail-inner"><div><span class="stay-source-type">${t(p.type)} · ${esc(p.area)}</span><h2 id="stay-dialog-title">${esc(p.name)}</h2><p>${esc(p.description[lang])}</p>${p.capacity?`<p>${t('capacity')} ${p.capacity} ${t('people')} · ${p.bedrooms} ${t(p.bedrooms===1?'bedroom':'bedrooms')}</p>`:''}${p.rating?`<p class="stay-rating">★ ${p.rating.score} / ${p.rating.scale} · ${p.rating.count} ${t('reviews')} · Airbnb</p><p>${t('ratingNote')}</p>`:''}<h3>${t('amenities')}</h3><div class="stay-detail-tags">${p.amenities.map(x=>`<span>${t(x)}</span>`).join('')}</div><h3>${t('where')}</h3><p>${esc(p.address||p.area)}${p.zone==='juarez'?' · Juárez, CDMX':''}</p>${p.address?`<a class="stay-detail-map" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.name+' '+p.address+' Ciudad de México')}" target="_blank" rel="noopener noreferrer">${t('location')}</a>`:`<p>${t('airbnbLocation')}</p>`}<p class="stay-detail-source">${t('realSource')} · <a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${esc(new URL(p.source).hostname)} ↗</a><br>${t('imageSource')} <a id="stay-image-credit" href="${esc(imgs[0].source)}" target="_blank" rel="noopener noreferrer">${esc(new URL(imgs[0].source).hostname)} ↗</a></p></div><aside class="stay-quote"><h3>${t('quote')}</h3><div class="stay-price"><strong>${money(v.unit)}</strong></div><p>${unitText(p)} · DEMO</p><p>${tripText(p)}<br>${trip.guests} ${t('people')} · ${v.count} ${t(v.count===1?'unit':'units')}</p><dl><div><dt>${t('nightly')} × ${v.periods} × ${v.count}</dt><dd>${money(v.base)}</dd></div>${v.discount?`<div><dt>${t('promoLine')} −${v.discount}%</dt><dd>−${money(v.base-v.total)}</dd></div>`:''}<div class="stay-quote-total"><dt>${t('stayTotal')}</dt><dd>${money(v.total)}</dd></div></dl><p>${t((p.type==='hotel'||p.type==='paso')?'roomRule':p.type==='hostel'?'bedRule':'aptRule')}</p>${hasOffer(p)?`<p>${p.type==='paso'?t('shortPromo'):t('noPromoDates')+' '+p.demoOfferNights+' '+t('nights')+'. '+t('promoCondition')}</p>`:''}<p>${t('quoteNote')}</p><a class="stay-primary" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${t('source')}</a><p>${t(p.type==='paso'?'shortAvailability':'availability')}</p></aside></div>`;dialog.showModal();$('#stay-close').focus();}
function close(){dialog.close();const key=lastFocus?.dataset.stay;active=null;(key?document.querySelector(`[data-stay="${key}"]`):lastFocus)?.focus();}
function reset(){type='all';savedOnly=false;$('#stay-search').value='';$('#stay-zone').value='';$('#stay-budget').value='8000';$('#stay-offers').checked=false;$$('[data-amenity]').forEach(x=>x.checked=false);render();}
function toast(text){clearTimeout(toastTimer);$('#stay-toast').textContent=text;$('#stay-toast').hidden=false;toastTimer=setTimeout(()=>$('#stay-toast').hidden=true,2800);}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-type],[data-stay],[data-save],[data-reset],[data-photo]');if(b?.dataset.type){type=b.dataset.type;render();}if(b?.dataset.stay){const p=stays.find(x=>x.id===b.dataset.stay);if(p)detail(p);}if(b?.dataset.save){const id=b.dataset.save;if(saved.has(id))saved.delete(id);else saved.add(id);try{sessionStorage.setItem('lavita-saved-stays',JSON.stringify([...saved]));}catch{}render();document.querySelector(`[data-save="${id}"]`)?.focus();toast(t(saved.has(id)?'savedToast':'removedToast'));}if(b?.hasAttribute('data-reset'))reset();if(b?.dataset.photo&&active){photo=(photo+Number(b.dataset.photo)+active.images.length)%active.images.length;$('#stay-detail-image').src=active.images[photo].local;$('#stay-photo-count').textContent=`${photo+1} / ${active.images.length}`;$('#stay-image-credit').href=active.images[photo].source;$('#stay-image-credit').textContent=new URL(active.images[photo].source).hostname+' ↗';}});
$('#stay-duration').onchange=()=>{trip.hours=+$('#stay-duration').value;render();};$('#stay-search').oninput=render;$('#stay-zone').onchange=render;$('#stay-budget').oninput=render;$('#stay-sort').onchange=render;$('#stay-offers').onchange=render;$$('[data-amenity]').forEach(x=>x.onchange=render);$('#saved-only').onclick=()=>{savedOnly=!savedOnly;render();};$('#stay-reset').onclick=reset;
$('#stay-checkin').onchange=()=>{const start=$('#stay-checkin').value;if(!start)return;$('#stay-checkout').min=plus(start,1);if($('#stay-checkout').value<=start)$('#stay-checkout').value=plus(start,2);};
$('#stay-trip').onsubmit=e=>{e.preventDefault();const start=$('#stay-checkin').value,end=$('#stay-checkout').value;$('#trip-message').hidden=false;if(start<today()){$('#trip-message').textContent=t('datePast');return;}if(type!=='paso'&&end<=start){$('#trip-message').textContent=t('dateError');return;}trip={start,end,guests:+$('#stay-guests').value,hours:+$('#stay-duration').value};$('#trip-message').textContent=t('tripUpdated');render();};
$('#language').onchange=()=>{lang=$('#language').value;try{sessionStorage.setItem('lavita-language',lang);}catch{}$('#trip-message').hidden=true;interfaceText();};$('#stay-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
$('#promos-prev').onclick=()=>$('#stay-promo-track').scrollBy({left:-300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#promos-next').onclick=()=>$('#stay-promo-track').scrollBy({left:300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
$('#profile-button').onclick=()=>toast($('#profile-name').textContent+' · '+$('#profile-points').textContent+' · '+t('demoOnly'));
